    out=[row[:] for row in g]
    # find rectangles: for each pair of rows and cols check border all lc
    rows=[i for i in range(h) if any(g[i][j]==lc for j in range(w))]
    colsL=[j for j in range(w) if any(g[i][j]==lc for i in range(h))]
    for r1 in rows:
        for r2 in rows:
            if r2<=r1+1: continue
            for c1 in colsL:
                for c2 in colsL:
